SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='agents' AND column_name='adapter')=0,'ALTER TABLE agents ADD COLUMN adapter VARCHAR(160) NULL','SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
